begin;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email,email_confirmed_at) values
 ('99000000-0000-4000-8000-000000000001','signup-test@example.invalid',null),
 ('99000000-0000-4000-8000-000000000002','second-signup@example.invalid',now()),
 ('99000000-0000-4000-8000-000000000003','team-signup@example.invalid',now());
create temporary table new_workspaces(user_id uuid,coop uuid);
grant all on new_workspaces to authenticated;
select ok(not has_function_privilege('anon','public.request_registration(text,text,text,text,text,text)','EXECUTE'),'Anonymous callers cannot submit authenticated registrations');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"99000000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal1"}',true);
select throws_ok($$select public.request_registration('trial_owner','Trial owner','Real workspace','Region','2468','trial')$$,'P0001','Confirmed email required','Email confirmation is required server-side');
reset role;
update auth.users set email_confirmed_at=now() where id='99000000-0000-4000-8000-000000000001';
set local role authenticated;
select lives_ok($$select public.request_registration('trial_owner','Trial owner','Real workspace','Region','2468','trial')$$,'Confirmed person requests a trial');
select is((select count(*)::integer from public.membership where user_id=auth.uid()),0,'Pending registration grants no membership');
select is((select count(*)::integer from public.cooperative),0,'Pending registration cannot read cooperative data');
select throws_ok($$select public.review_registration(auth.uid(),'approved','full','Self approval')$$,'P0001','Admin AAL2 required','Applicant cannot approve themselves');
select set_config('request.jwt.claims','{"sub":"99000000-0000-4000-8000-000000000002","role":"authenticated","aal":"aal1"}',true);
select lives_ok($$select public.request_registration('second_owner','Second owner','Second workspace','Region','2468','full')$$,'Second person requests full access');
select is((select count(*)::integer from public.registration_request),1,'Applicants see only their own request');
select set_config('request.jwt.claims','{"sub":"20000000-0000-4000-8000-000000000004","role":"authenticated","aal":"aal1"}',true);
select throws_ok($$select public.review_registration('99000000-0000-4000-8000-000000000001','approved','trial','Verified owner')$$,'P0001','Admin AAL2 required','Admin needs MFA to approve');
select set_config('request.jwt.claims','{"sub":"20000000-0000-4000-8000-000000000004","role":"authenticated","aal":"aal2"}',true);
insert into new_workspaces values('99000000-0000-4000-8000-000000000001',public.review_registration('99000000-0000-4000-8000-000000000001','approved','trial','Verified owner'));
insert into new_workspaces values('99000000-0000-4000-8000-000000000002',public.review_registration('99000000-0000-4000-8000-000000000002','approved','full','Verified organization'));
select is((select service_plan from public.cooperative where id=(select coop from new_workspaces where user_id='99000000-0000-4000-8000-000000000001')),'trial','Administrator grants an explicit trial plan');
select is((select count(*)::integer from public.lot where cooperative_id in(select coop from new_workspaces)),0,'New workspaces contain no generated lots');
select is((select count(*)::integer from public.supplier where cooperative_id in(select coop from new_workspaces)),0,'New workspaces contain no generated suppliers');
select is((select count(*)::integer from public.sale where cooperative_id in(select coop from new_workspaces)),0,'New workspaces contain no generated sales');
select is((select roles from public.membership where user_id='99000000-0000-4000-8000-000000000001'),array['manager','producer'],'Registration never grants platform-admin or reviewer roles');
select set_config('request.jwt.claims','{"sub":"20000000-0000-4000-8000-000000000007","role":"authenticated","aal":"aal1"}',true);
select is((select count(*)::integer from public.dashboard_cooperatives() where id=(select coop from new_workspaces where user_id='99000000-0000-4000-8000-000000000001')),0,'Donor filters exclude trial workspaces');
select set_config('request.jwt.claims','{"sub":"20000000-0000-4000-8000-000000000004","role":"authenticated","aal":"aal2"}',true);
select is(jsonb_array_length(public.operational_dashboard(current_date,current_date,null,null,null,null)->'cooperatives'),(select count(*)::integer from public.cooperative where service_plan='full'),'Global operational reporting excludes trials');
select throws_ok($$select public.review_registration('99000000-0000-4000-8000-000000000001','approved','full','Duplicate approval')$$,'P0001','Pending request required','Repeated approval cannot create another workspace');
reset role;
select ok((select pin_hash=extensions.crypt('2468',pin_hash) and pin_hash<>'2468' from private.user_pin where user_id='99000000-0000-4000-8000-000000000001'),'PIN transferred as a password hash');
select is((select count(*)::integer from private.registration_pin),0,'Approved requests no longer retain pending PIN hashes');
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select throws_ok($$select public.provision_membership('99000000-0000-4000-8000-000000000003',(select coop from new_workspaces where user_id='99000000-0000-4000-8000-000000000001'),'third_member','Third member',array['producer'],'{}','2468','20000000-0000-4000-8000-000000000004')$$,'P0001','Trial workspace is limited to one account','Trial cannot add team members through direct provisioning');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"99000000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal1"}',true);
select is((select count(*)::integer from public.cooperative),1,'Trial account sees only its own workspace');
select is((select count(*)::integer from public.dashboard_cooperatives()),1,'Trial owner can view their own workspace reports');
select is((select count(*)::integer from public.lot),0,'Trial account cannot read seeded production data');
select throws_ok($$select public.upgrade_workspace((select coop from new_workspaces where user_id=auth.uid()),'Self upgrade')$$,'P0001','Admin AAL2 required','Trial cannot upgrade itself');
select lives_ok($$select public.manage_registry('supplier',gen_random_uuid(),jsonb_build_object('cooperative_id',(select coop from new_workspaces where user_id=auth.uid()),'name','User entered supplier','type','dairy','status','approved'))$$,'Approved founder can register actual suppliers');
select throws_ok($$select public.manage_registry('supplier',gen_random_uuid(),jsonb_build_object('cooperative_id',(select coop from new_workspaces where user_id='99000000-0000-4000-8000-000000000002'),'name','Cross-scope supplier','type','dairy','status','approved'))$$,'P0001','Admin permission required','Founder cannot modify another workspace');
select set_config('request.jwt.claims','{"sub":"20000000-0000-4000-8000-000000000004","role":"authenticated","aal":"aal2"}',true);
select lives_ok($$select public.upgrade_workspace((select coop from new_workspaces where user_id='99000000-0000-4000-8000-000000000001'),'Organization approved')$$,'Admin upgrades trial to full service');
select is((select service_plan from public.cooperative where id=(select coop from new_workspaces where user_id='99000000-0000-4000-8000-000000000001')),'full','Upgrade persists');
select * from finish();
rollback;
